    var body: some View {
        switch pane {
        case .general: GeneralSettingsView()
        case .appearance: AppearanceSettingsView()
        case .tabs: TabsSettingsView()
        case .ai: ModelsSettingsView()
        case .passwords: PasswordsImportView()
        case .privacy: PersonalizationSettingsView()
        case .extensions: ExtensionsSettingsView()
        case .agents: AgentsSettingsView()
        case .about: AboutSettingsView()
        }
    }
}

/// Chrome's "Search settings" field: a rounded pill with a magnifier and a clear button.
private struct SettingsSearchField: View {
    @Binding var text: String
    @FocusState private var focused: Bool

    var body: some View {
        HStack(spacing: 8) {
            Image(systemName: "magnifyingglass")
                .font(.system(size: 13, weight: .medium))
                .foregroundStyle(.secondary)
            TextField("Search settings", text: $text)
                .textFieldStyle(.plain)
                .font(.system(size: 13.5))
                .focused($focused)
                .onExitCommand { text = "" }
            if !text.isEmpty {
                Button { text = "" } label: {
                    Image(systemName: "xmark.circle.fill")
                        .font(.system(size: 13))
                        .foregroundStyle(.secondary)
                }
                .buttonStyle(.plain)
                .accessibilityLabel("Clear search")
            }
        }
        .padding(.horizontal, 14)
        .frame(height: 38)
        .background(Capsule(style: .continuous).fill(focused ? SettingsStyle.card : SettingsStyle.field))
        .overlay(Capsule(style: .continuous)
            .strokeBorder(focused ? LunaSurface.accent.opacity(0.9) : Color.clear, lineWidth: 1.5))
        .contentShape(Capsule())
        .onTapGesture { focused = true }
    }
}

/// A pane in the left nav: icon and title; the selected pane gets an accent-tinted pill.
private struct SettingsNavRow: View {
    let pane: SettingsPane
    let isSelected: Bool
    let action: () -> Void
    @State private var hovering = false

    var body: some View {
        Button(action: action) {
            HStack(spacing: 14) {
                Image(systemName: pane.icon)
                    .font(.system(size: 13.5, weight: isSelected ? .semibold : .regular))
                    .foregroundStyle(isSelected ? LunaSurface.accent : Color.secondary)
                    .frame(width: 20)
                Text(pane.title)
                    .font(.system(size: 13, weight: isSelected ? .semibold : .regular))
                    .foregroundStyle(isSelected ? LunaSurface.accent : Color.primary)
                Spacer(minLength: 0)
            }
            .padding(.horizontal, 14)
            .frame(height: 34)
            .background(Capsule(style: .continuous)
                .fill(isSelected ? LunaSurface.accent.opacity(0.14) : (hovering ? LunaSurface.hover : .clear)))
            .contentShape(Capsule())
        }
        .buttonStyle(.plain)
        .onHover { hovering = $0 }
        .accessibilityLabel(pane.title)
        .accessibilityAddTraits(isSelected ? [.isButton, .isSelected] : .isButton)
    }
}

// MARK: - Search

/// A setting the search field can find: its pane, label and description, and its registry key when
/// it has one (then the result is the live control itself).
struct SettingsSearchItem: Hashable {
    let pane: SettingsPane
    let title: String
    var subtitle: String?
    var registryKey: String?

    func matches(_ query: String) -> Bool {
        title.lowercased().contains(query) || (subtitle?.lowercased().contains(query) ?? false)
    }
}

extension SettingsPane {
    /// Every searchable row in this pane: its registry settings, then the other rows.
    var searchItems: [SettingsSearchItem] {
        registryKeys.compactMap { key in
            CustomizationRegistry.setting(key).map {
                SettingsSearchItem(pane: self, title: $0.title, subtitle: $0.help, registryKey: key)
            }
        } + otherRows.map { SettingsSearchItem(pane: self, title: $0.0, subtitle: $0.1) }
    }

    /// Rows that aren't registry settings (labels as shown in the pane).
    private var otherRows: [(String, String?)] {
        switch self {
        case .general: return [("Default browser", "Make Luna open your links."), ("Profiles", "Rename, recolor, add and delete profiles."),
                               ("Add Profile", nil), ("Welcome", "Show the welcome tour again.")]
        case .appearance: return [("Layout template", "Luna or Chrome look in one click."),
                                  ("Theme colors", "Presets, accent, window, sidebar and tab colors."),
                                  ("Tab layout", nil), ("Wallpaper", "Start page wallpaper and moon."),
                                  ("Moon style", nil), ("Frame rate", nil), ("Remove all shortcuts", "Start page shortcuts.")]
        case .tabs: return []
        case .ai: return [("Model", "Which AI model Luna uses."), ("API keys", "Keys for cloud model providers."),
                          ("Ollama", "Local models on this Mac."), ("Luna Max", "Ask on page, link previews and tidy features."),
                          ("Computer use", nil), ("Text size", "AI panel text size.")]
        case .passwords: return [("Passwords", "Saved logins in the Luna vault."), ("iCloud Keychain sync", nil),
                                 ("Import", "Bring bookmarks, history and passwords from another browser."),
                                 ("Import passwords from CSV", nil)]
        case .privacy: return [("Keep a usage record", "Counts the Luna features and shortcuts you use each day, on this Mac only."),
                               ("Keep data for", nil), ("View usage data", nil),
                               ("Cookies and site data", "Clear cookies and site data."),
                               ("Clear browsing data", "Clear history for a time range.")]
        case .extensions: return [("Extensions", "Installed extensions."), ("Chrome Web Store", "Add extensions.")]
        case .agents: return [("Let agents drive Luna", "An MCP server for Claude Code, Codex and other agents, on this Mac only."),
                              ("Port", nil), ("Don't ask before agents act", nil), ("Regenerate token", nil),
                              ("Enable Developer Tools", "Adds Inspect Element to the page's context menu."),
                              ("Recent AI changes", "Changes your AI agent made, with Undo.")]
        case .about: return [("Version", nil), ("License", nil), ("Source code on GitHub", nil)]
        }
    }
}

/// Search results: the matching rows of every pane, grouped by pane in cards.
private struct SettingsSearchResults: View {
    let query: String
    let open: (SettingsPane) -> Void

    private struct ResultGroup: Identifiable {
        let pane: SettingsPane
        let items: [SettingsSearchItem]
        var id: SettingsPane { pane }
    }

    private var groups: [ResultGroup] {
        let q = query.lowercased()
        return SettingsPane.available.compactMap { pane in
            let items = pane.searchItems.filter { $0.matches(q) }
            if !items.isEmpty { return ResultGroup(pane: pane, items: items) }
            // The pane matches by name or keyword but no single row does: offer the pane.
            return pane.matches(q) ? ResultGroup(pane: pane, items: []) : nil
        }
    }

    var body: some View {
        let groups = groups
        SettingsPage("Search results") {
            if groups.isEmpty {
                VStack(spacing: 10) {
                    Image(systemName: "magnifyingglass")
                        .font(.system(size: 28, weight: .light))
                        .foregroundStyle(.secondary)
                    Text("No settings match “\(query)”")
                        .font(.system(size: 14, weight: .medium))
                    Text("Try another word, like “theme”, “passwords” or “model”.")
                        .font(.system(size: 12))
                        .foregroundStyle(.secondary)
                }
                .frame(maxWidth: .infinity)
                .padding(.top, 60)
            }
            ForEach(groups) { group in
                SettingsCard(group.pane.title) {
                    ForEach(group.items, id: \.self) { item in
                        if let key = item.registryKey {
                            RegistryControl(key: key)
                        } else {
                            SettingsLinkRow(item.title, subtitle: item.subtitle) { open(group.pane) }
                        }
                    }
                    SettingsLinkRow("All \(group.pane.title) settings", icon: group.pane.icon) { open(group.pane) }
                }
            }
        }
    }
}

/// The live control for a registry setting, by its kind.
struct RegistryControl: View {
    let key: String

    var body: some View {
        switch CustomizationRegistry.setting(key)?.kind {
        case .bool: RegistryToggle(key)
        case .choice: RegistryPicker(key)
        case .intChoice: RegistryIntPicker(key)
        default: EmptyView()
        }
    }
}

/// AppKit focuses the first text field (General's profile name) when Settings opens. Start with
/// nothing focused instead, like System Settings: each time the Settings tab (or a standalone
/// window) appears, and again whenever a standalone window reopens after closing.
private struct SettingsInitialFocus: NSViewRepresentable {
    func makeNSView(context: Context) -> NSView { FocusView() }
    func updateNSView(_ view: NSView, context: Context) {}

    private final class FocusView: NSView {
        private var observers: [NSObjectProtocol] = []
        private var reopening = false

        override func hitTest(_ point: NSPoint) -> NSView? { nil }

        override func viewDidMoveToWindow() {
            observers.forEach(NotificationCenter.default.removeObserver)
            observers = []
            guard let window else { return }
            clearTextFocus()
            let center = NotificationCenter.default
            observers.append(center.addObserver(forName: NSWindow.willCloseNotification, object: window, queue: .main) { [weak self] _ in
                self?.reopening = true
            })
            observers.append(center.addObserver(forName: NSWindow.didBecomeKeyNotification, object: window, queue: .main) { [weak self] _ in
                guard let self, self.reopening else { return }
                self.reopening = false
                self.clearTextFocus()
            })
        }

        private func clearTextFocus() {
            DispatchQueue.main.async { [weak self] in
                guard let window = self?.window, window.firstResponder is NSText else { return }
                window.makeFirstResponder(nil)
            }
        }

        deinit { observers.forEach(NotificationCenter.default.removeObserver) }
    }
}

/// A standalone Settings window: the pane header is the title, so no window title or titlebar material.
private struct StandaloneWindowChrome: ViewModifier {
    let enabled: Bool
    func body(content: Content) -> some View {
        if enabled {
            content
                .ignoresSafeArea(.container, edges: .top)
                .toolbar(removing: .title)
                .toolbarBackgroundVisibility(.hidden, for: .windowToolbar)
        } else {
            content
        }
    }
}

enum SettingsPane: String, CaseIterable, Identifiable, Hashable {
    case general, appearance, tabs, ai, passwords, privacy, extensions, agents, about

    /// Panes this build shows. Agents is in both builds (Connect agents); its Dev mode part is Luna Dev only.
    static var available: [SettingsPane] { allCases }

    /// Pane names from before the settings rework (menus, scripts, `LUNA_SNAPSHOT_SETTINGS`, debug driver)
    /// → the pane that holds those settings now.
    static let legacyNames: [String: SettingsPane] = [
        "profiles": .general,
        "search": .general,
        "import": .passwords,
        "importData": .passwords,
        "lunaMax": .ai,
        "personalization": .privacy,
        "dev": .agents,
        "developer": .agents,
    ]

    /// A pane by its name, old or new.
    static func resolve(_ name: String) -> SettingsPane? {
        SettingsPane(rawValue: name) ?? legacyNames[name]
    }

    /// The Passwords & Import tab an old pane name meant, if any.
    static func passwordsTab(for name: String) -> PasswordsPaneTab? {
        switch name {
        case "import", "importData": return .importData
        case SettingsPane.passwords.rawValue: return .passwords
        default: return nil
        }
    }

    var id: String { rawValue }

    var title: String {
        switch self {
        case .general: return "General"
        case .appearance: return "Appearance"
        case .tabs: return "Tabs & Sidebar"
        case .ai: return "AI"
        case .passwords: return "Passwords & Import"
        case .privacy: return "Privacy & Data"
        case .extensions: return "Extensions"
        case .agents: return "Agents"
        case .about: return "About Luna"
        }
    }

    var icon: String {
        switch self {
        case .general: return "gearshape"
        case .appearance: return "paintbrush"
        case .tabs: return "square.on.square"
        case .ai: return "sparkles"
        case .passwords: return "key.fill"
        case .privacy: return "hand.raised"
        case .extensions: return "puzzlepiece.extension"
        case .agents: return "chevron.left.forwardslash.chevron.right"
        case .about: return "info.circle"
        }
    }

    /// Registry settings shown in this pane; their labels are searchable too.
    var registryKeys: [String] {
        switch self {
        case .general: return ["search.engine", "search.suggestions"]
        case .appearance: return ["layout.template", "appearance.theme", "appearance.liquidGlass", "tabs.layout",
                                  "toolbar.visible", "bookmarksBar.visible", "chrome.autoHide", "chrome.alwaysShowTopBar",
                                  "chrome.roundedFrame", "chrome.homeButton", "chrome.hideWindowButtons", "addressBar.centered",
                                  "addressBar.minimalURL", "addressBar.loadingProgress", "startPage.showShortcuts",
                                  "appearance.density", "appearance.cornerRadius", "appearance.fontScale", "appearance.contrast",
                                  "glass.blur", "glass.tint"] + GlassSurface.allCases.map(\.registryKey)
        case .tabs: return ["tabs.unloadAfterMinutes"]
        case .ai: return ["aiPanel.fontSize", "lunaMax.askOnPage", "lunaMax.linkPreviews", "lunaMax.tidyTitles",
                          "lunaMax.tidyDownloads"]
        case .passwords, .privacy, .extensions, .agents, .about: return []
        }
    }

    /// Words that find this pane from the search field.
    var keywords: [String] {
        switch self {
        case .general: return ["default browser", "profile", "account", "window", "search engine", "suggestions",
                               "welcome", "onboarding", "startup"]
        case .appearance: return ["theme", "dark", "light", "layout", "template", "chrome", "custom", "customize", "sidebar",
                                  "compact", "dynamic", "classic", "address", "url", "frameless", "frame", "auto-hide",
                                  "home", "toolbar", "bookmarks", "wallpaper", "background", "shader", "moon", "glass",
                                  "accent", "color", "colour", "preset", "density", "radius", "corner", "font", "text size",
                                  "contrast", "blur", "tint",
                                  "start page", "shortcuts"]
        case .tabs: return ["tabs", "memory", "unload", "sleep", "hibernate", "inactive"]
        case .ai: return ["model", "gemini", "ollama", "openai", "chatgpt", "anthropic", "claude", "api key", "luna max",
                          "ask on page", "preview", "tidy", "rename", "downloads", "arc max", "folders", "jev",
                          "computer use", "agent", "grab", "text size"]
        case .passwords: return ["password", "login", "keychain", "autofill", "icloud", "touch id", "import", "chrome",
                                 "firefox", "safari", "brave", "edge", "arc", "vivaldi", "1password", "csv",
                                 "bookmarks", "history", "sync"]
        case .privacy: return ["privacy", "usage", "data", "record", "personalization", "cookies", "site data",
                               "history", "clear", "browsing data", "customize"]
        case .extensions: return ["extension", "add-on", "plugin", "chrome web store", "ublock", "adblock"]
        case .agents: return ["mcp", "connect agents", "port", "token", "claude code", "codex", "harness", "cli",
                                 "terminal", "dev mode", "sync", "approval", "developer", "recent ai changes", "undo", "changes"]
        case .about: return ["version", "license"]
        }
    }

    /// True when `query` (lowercased) names this pane, one of its keywords or one of its settings.
    func matches(_ query: String) -> Bool {
        title.lowercased().contains(query)
            || keywords.contains { $0.contains(query) }
            || registryKeys.contains { CustomizationRegistry.setting($0)?.title.lowercased().contains(query) ?? false }
    }
}

